class Holder { public C Captured = new C(0); }
class C {
    public readonly int Value;
    public C(int value) { Value = value; }
    public C(Holder holder) : this(5) { holder.Captured = this; Value += 2; }
    public C(Holder holder, string tag) : this(holder) { Print(holder.Captured == this); Print(tag); Value += 3; }
}
void Main() { var h = new Holder(); var c = new C(h, "outer"); Print(c == h.Captured); Print(c.Value); }
